//! Oracle tier: reads Goldmark artifacts regenerated by
//! `scripts/regen-fixtures.py` (see docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_text::markdown::{
    block_reader::BlockReader, bytes::Bytes, reader::Reader, text::Segment,
};
use serde::Deserialize;
use serde_json::{Value, json};
#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Request {
    source: String,
    #[serde(default)]
    size: usize,
    capacity: usize,
    segment: Segment,
}
#[derive(Deserialize)]
struct Fixture {
    requests: Vec<Request>,
    results: Vec<Value>,
}
fn hex(bytes: &[u8]) -> String {
    fn raw(bytes: &[u8]) -> String {
        bytes.iter().map(|b| format!("{b:02x}")).collect()
    }
    if bytes.len() <= 2048 {
        return raw(bytes);
    }
    let mut result = String::from("rle4:");
    let mut chunks = bytes.chunks(4).peekable();
    while let Some(chunk) = chunks.next() {
        let mut count = 1;
        while chunks.peek().is_some_and(|next| *next == chunk) {
            count += 1;
            chunks.next();
        }
        result.push_str(&format!("{}*{count};", raw(chunk)));
    }
    result
}
fn value_hex(value: Option<Bytes>) -> String {
    value.map_or_else(String::new, |b| hex(&b.bytes()))
}
#[test]
fn pinned_goldmark_shared_source_aliases() {
    let f: Fixture = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/aliases.json"
    ))
    .unwrap();
    assert!(!f.requests.is_empty());
    assert_eq!(f.requests.len(), f.results.len());
    for (i, (q, expected)) in f.requests.iter().zip(&f.results).enumerate() {
        let mut data: Vec<_> = (0..q.source.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&q.source[i..i + 2], 16).unwrap())
            .collect();
        if q.size > 0 {
            data = (0..q.size).map(|i| b"abcd"[i % 4]).collect();
        }
        let source = Bytes::with_capacity(&data, q.capacity);
        let mut r = Reader::with_source(source.clone());
        let cached = r.peek_line().0;
        let segments = [q.segment];
        let mut b = BlockReader::with_source(source.clone(), Some(&segments));
        let value = q.segment.value_shared(&source);
        let first = hex(&value.bytes());
        let source_after = hex(&source.bytes());
        let backing_after = hex(&source.slice(0, source.capacity()).bytes());
        if !source.is_empty() {
            source.set(0, b'!');
        }
        let again = r.peek_line().0;
        let block = b.peek_line().0;
        let actual = json!({"first":first,"value":hex(&value.bytes()),"capacity":value.capacity(),"source_after_value":source_after,"backing_after_value":backing_after,"source":hex(&source.bytes()),"cached":value_hex(cached),"again":value_hex(again),"block":value_hex(block)});
        assert_eq!(&actual, expected, "case {i}");
    }
}
